import React from 'react';
import { FaMapMarkerAlt, FaPhoneAlt, FaEnvelope } from 'react-icons/fa';
import '../styles.css';

const Profile = () => (
  <section id="profile">
    <div className="profile-info">
      <img 
        src="https://github.com/Monwabisindlovu/portfolio-landing_page/blob/main/images/pqjjw8cr.png?raw=true" 
        alt="Monwabisi Ndlovu" 
        className="profile-img" 
      />
      <p className="profile-details">
        <span className="profile-text"><FaMapMarkerAlt className="profile-icon" /> Johannesburg, South Africa</span>
        <span className="profile-text"><FaPhoneAlt className="profile-icon" /> +27849621939</span>
        <span className="profile-text"><FaEnvelope className="profile-icon" /> monwabisindlovu78@gmail.com</span>
      </p>
    </div>
  </section>
);

export default Profile;
